<?php
namespace App\Services; use App\Models\User; use App\Repositories\UserRepository; use Illuminate\Support\Arr; use Illuminate\Support\Facades\DB;
class UserService { public function __construct(private UserRepository $repo){} public function create(array $data): User{return DB::transaction(function()use($data){$role=$data['role'];$user=$this->repo->create(Arr::except($data,['role']));$user->syncRoles([$role]);return $user;});} public function update(User $user,array $data): User{return DB::transaction(function()use($user,$data){$role=$data['role']; if(empty($data['password'])) unset($data['password']); $user=$this->repo->update($user,Arr::except($data,['role']));$user->syncRoles([$role]);return $user;});} public function delete(User $user): void{DB::transaction(fn()=> $this->repo->delete($user));} }
